 \begin{array}{l}
 \nabla_X(xm)=X(x)m +x\nabla_X(m)\\
 \\
 \nabla_{zX}(m)=z\nabla_X(m)
 \end{array}
 \right.
  \label{covder}$$ for any $m\in M$, $x\in J$ and $z\in Z(J)$.\
